/**
 * 3474. Lexicographically Smallest Generated String
 * https://leetcode.com/problems/lexicographically-smallest-generated-string
 * 
 * You are given two strings, str1 and str2, of lengths n and m, respectively.
 * A string word of length n + m - 1 is defined to be generated by str1 and str2 if it satisfies the following conditions for each index 0 <= i <= n - 1:
 *     1)If str1[i] == 'T', the substring word with size m starting at index i equal str2, i.e., word[i..(i + m - 1)] == str2.
 *     2)If str1[i] == 'F', the substring word with size m starting at index i not equal str2, i.e., word[i..(i + m - 1)] != str2.
 * 
 * Return the lexicographically smallest possible string that can be generated by str1 and str2. If no string can be generated, return an empty string "".
 * 
 * Example 1:
 *     Input: str1 = "TFTF", str2 = "ab"
 *     Output: "ababa"
 *     Explanation: The table below represents the string "ababa"
 *        ---------------------------------------
 *        | Index |  T/F  | Substring of length |
 *         --------------------------------------
 *        |   0   |  'T'  | "ab"                |
 *        |   1   |  'F'  | "ba"                |
 *        |   2   |  'T'  | "ab"                |
 *        |   3   |  'F'  | "ba"                |
 *        ---------------------------------------
 *        The strings "ababa" and "ababb" can be generated by str1 and str2.
 *        Return "ababa" since it is the lexicographically smaller string.
 * 
 * Example 2:
 *     Input: str1 = "TFTF", str2 = "abc"
 *     Output: ""
 *     Explanation: No string that satisfies the conditions can be generated.
 * 
 * Example 3:
 *     Input: str1 = "F", str2 = "d"
 *     Output: "a"
 * 
 * Constraints:
 *     1 <= n == str1.length <= 10^4
 *     1 <= m == str2.length <= 500
 *     str1 consists only of 'T' or 'F'
 *     str2 consists only of lowercase English characters
 */

#include <cassert>
#include <string>
#include <vector>

class Solution {
public:
    std::string generateString(const std::string& str1, const std::string& str2) {
        const int n = str1.length();
        const int m = str2.length();

        std::string ans(n + m - 1, '?');
        for (int i = 0; i < n; ++i) {
            if (str1[i] != 'T') {
                continue;
            }
            for (int j = i; j < i + m; ++j) {
                if (ans[j] != '?' && ans[j] != str2[j - i]) {
                    return "";
                }
                ans[j] = str2[j - i];
            }
        }

        std::vector<std::vector<int>> last_chance(ans.length());
        for (int i = 0; i < n; ++i) {
            if (str1[i] != 'F') {
                continue;
            }
            bool is_found_pos = false;
            for (int j = i + m - 1; j >= i; --j) {
                if (ans[j] == '?') {
                    last_chance[j].push_back(i);
                    is_found_pos = true;
                    break;
                }
            }
            
            if (!is_found_pos && ans.compare(i, m, str2) == 0) {
                return "";
            }

        }

        for (int i = 0; i < static_cast<int>(ans.length()); ++i) {
            if (ans[i] != '?') {
                continue;
            }
            bool forbidden[26] = {false};

            auto is_equal_str = [&](int start){
                bool is_equal = true;
                for (int k = 0; k < m; ++k) {
                    if (start + k != i && str2[k] != ans[start + k]) {
                        return false;
                    }
                }
                return is_equal;
            };

            for (int j : last_chance[i]) {
                if (is_equal_str(j)) {
                    forbidden[str2[i - j] - 'a'] = true;
                }
            }

            ans[i] = 'a';
            while (forbidden[ans[i] - 'a']) {
                ++ans[i];
                if (ans[i] > 'z') {
                    return "";
                }
            }
        }
        return ans;
    }
};

void Test1() {
    std::string str1 = "TFTF";
    std::string str2 = "ab";
    assert(Solution().generateString(str1, str2) == std::string("ababa"));
}

void Test2() {
    std::string str1 = "TFTF";
    std::string str2 = "abc";
    assert(Solution().generateString(str1, str2) == std::string(""));
}

void Test3() {
    std::string str1 = "F";
    std::string str2 = "d";
    assert(Solution().generateString(str1, str2) == std::string("a"));
}

int main() {
    Test1();
    Test2();
    Test3();
    return 0;
}